entries[429634] = { ["name"] = "Colossal Might", ["text"] = "Arms\nColossal Might increases damage dealt by your next Demolish by 10%, stacking up to 5 times.\n\nMortal Strike grants a stack of Colossal Might and Cleave grants a stack of Colossal Might when it strikes 3 or more targets.\n\nProtection\nColossal Might increases damage dealt by your next Demolish by 10%, stacking up to 5 times.\n\nShield Slam grants a stack of Colossal Might and Revenge grants a stack of Colossal Might when it strikes 3 or more targets." }
