entries[429636] = { ["name"] = "Dominance of the Colossus", ["text"] = "Arms\nColossal Might now stacks up to 10 times. If you would gain a stack of Colossal Might and are at max stacks, the cooldown of Demolish is reduced by 2 sec.\n\nEnemies affected by Demolish take up to 10% more damage from you and deal up to 10% less damage to you for 10 sec based on the number of stacks of Colossal Might consumed by Demolish.\n\nProtection\nColossal Might now stacks up to 10 times. If you would gain a stack of Colossal Might and are at max stacks, the cooldown of Demolish is reduced by 4 sec.\n\nEnemies affected by Demolish take up to 20% more damage from you and deal up to 10% less damage to you for 10 sec based on the number of stacks of Colossal Might consumed by Demolish." }
entries[429637] = { ["name"] = "One Against Many", ["text"] = "Arms\nShockwave, Cleave, and Whirlwind deal 5% more damage per target affected up to 5.\n\nProtection\nShockwave, Revenge, and Whirlwind deal 3% more damage per target affected up to 5." }
